  var D = window.M1DATA, K = window.MRKQ10; if (!D || !D.topics || !K) return;
  var n = (window.M1 && M1.MOD && +M1.MOD.n) || (window.M1CONFIG && M1CONFIG.MOD && +M1CONFIG.MOD.n) || 1;
